from typing import Any, Dict, Optional
import json
import os


class ConfigLoader:
    """Class to load JSON configuration files with defaults."""

    def __init__(self, filepath: str, defaults: Optional[Dict[str, Any]] = None):
        self.filepath = filepath
        self.defaults = defaults if defaults is not None else {}

    def load(self) -> Dict[str, Any]:
        """Load the configuration file, merging with defaults if the file is missing."""
        if not os.path.exists(self.filepath):
            return self.defaults

        with open(self.filepath, 'r') as file:
            config = json.load(file)

        # Merge defaults with config, with config values taking precedence
        return {**self.defaults, **config}


