class JsonLogFormatter:
    def __init__(self, include_time: bool = True, include_level: bool = True):
        self.include_time = include_time
        self.include_level = include_level

    def format(self, record: Dict[str, Any]) -> str:
        log_entry = {}

        if 'msg' in record:
            log_entry['message'] = record['msg']

        if 'levelname' in record and self.include_level:
            log_entry['level'] = record['levelname']

        if 'created' in record and self.include_time:
            log_entry['time'] = record['created']

        return json.dumps(log_entry)

