import json
from logging import Formatter, LogRecord

class JsonFormatter(Formatter):
    """A logging formatter that outputs log records as JSON."""

    def __init__(self, *, timestamp_format: str = '%Y-%m-%d %H:%M:%S', **kwargs):
        super().__init__(**kwargs)
        self.timestamp_format = timestamp_format

    def format(self, record: LogRecord) -> str:
        """Format a log record as JSON."""
        if not isinstance(record, LogRecord):
            raise TypeError(f'Expected LogRecord, got {type(record).__name__}')

        log_entry = {
            'name': record.name,
            'level': record.levelname,
            'message': record.getMessage(),
            'time': record.asctime,
        }

        if record.exc_info:
            log_entry['exc_info'] = self.formatException(record.exc_info)

        return json.dumps(log_entry, default=str, ensure_ascii=False, indent=None)

    def formatException(self, exc_info: tuple) -> str:
        """Format exception information as JSON."""
        if not exc_info:
            return None

        exc_type, exc_value, exc_traceback = exc_info
        return {
            'type': exc_type.__name__,
            'message': str(exc_value),
            'traceback': self.format_stack(exc_traceback)
        }

    def format_stack(self, stack_info: list) -> str:
        """Format stack information as JSON."""
        return {
            'filename': stack_info.filename,
            'lineno': stack_info.lineno,
            'function': stack_info.function,
            'code_context': stack_info.code_context,
            'index': stack_info.index
        }

    def formatTime(self, record: LogRecord, datefmt: str = None) -> str:
        """Format the time of the record using the specified format."""
        record.asctime = record.created
        return super().formatTime(record, datefmt)

